import 'dart:io';
import '../../benchmark/value_store/tool_support.dart';

Future<void> main(List<String> args) async {
  final root = Directory(args.single).absolute.path;
  final manifest = readJson('$root/manifest.json');
  final out = Directory('$root/notifications-recheck')..createSync();
  final runs = <String, Object>{};
  final receipts = <Object>[];
  const variants = ['document_before', 'document_before_paths', 'combined', 'document_paths'];
  for (var pass = 1; pass <= 3; pass++) {
    for (final variant in pass.isOdd ? variants : variants.reversed) {
      final app = manifest['artifacts']['$variant/aot']['app'] as String;
      final binary = '$app/Contents/MacOS/loon_profile';
      final name = '$pass-$variant';
      final output = '${out.path}/$name.json';
      if (File(output).existsSync()) throw StateError('Existing $output');
      final loadBefore = await commandOutput(['sysctl', '-n', 'vm.loadavg']);
      final watch = Stopwatch()..start();
      final result = await Process.run(binary, [], environment: {
        ...Platform.environment,
        'PROFILE_VARIANT': variant,
        'PROFILE_EXPECT_MODE': 'aot',
        'PROFILE_SUITE': 'dependency',
        'PROFILE_CASE': '10k_four_queries',
        'PROFILE_WARMUPS': '10',
        'PROFILE_WARMUP_MS': '1000',
        'PROFILE_TRIALS': '21',
        'PROFILE_OUTPUT': output,
        'PROFILE_EXIT': 'true',
      });
      File('${out.path}/$name.log').writeAsStringSync('${result.stdout}\n${result.stderr}');
      if (result.exitCode != 0 || !File(output).existsSync()) throw StateError('Failed $name');
      final data = readJson(output);
      if (data['mode'] != 'aot' || data['variant'] != variant || data['exit_code'] != 0) throw StateError('Invalid $name');
      runs[name] = data;
      receipts.add({'job': name, 'binary': binary, 'binary_sha256': hashFile(binary),
        'exit_code': result.exitCode, 'elapsed_ms': watch.elapsedMilliseconds,
        'load_before': loadBefore, 'load_after': await commandOutput(['sysctl', '-n', 'vm.loadavg'])});
      final row = (data['rows'] as List).cast<Map>().singleWhere((r) => r['name'] == '10k_four_queries/total');
      stdout.writeln('$name: ${milliseconds(row['median_us'] as num)} ms');
    }
  }
  writeJson('${out.path}/results.json', {'manifest': manifest, 'runs': runs, 'receipts': receipts, 'collector_sha256': hashFile(File.fromUri(Platform.script).path)});
}
